// Conceptual fast-path / slow-path structure of a Linux futex lock:
void raw_futex_lock(_Atomic uint32_t *f) {
    uint32_t c = 0;
    if (atomic_compare_exchange_strong_explicit(f, &c, 1, memory_order_acquire, memory_order_relaxed))
        return; // Fast path: acquired in userspace with ZERO syscalls!
    do {
        if (c == 2 || atomic_compare_exchange_strong_explicit(f, &c, 2, memory_order_acquire, memory_order_relaxed))
            syscall(SYS_futex, f, FUTEX_WAIT_PRIVATE, 2, NULL, NULL, 0);
        c = 0;
    } while (!atomic_compare_exchange_strong_explicit(f, &c, 2, memory_order_acquire, memory_order_relaxed));
}

