void enable_denormal_flush_to_zero(void) {
    // Set Flush-To-Zero (FTZ, bit 15) and Denormals-Are-Zero (DAZ, bit 6) in x86 MXCSR
    _MM_SET_FLUSH_ZERO_MODE(_MM_FLUSH_ZERO_ON);
