#include <stddef.h>

void vec_fma(float * restrict out, const float * restrict a,
             const float * restrict b, float scale, size_t n) {
    out = __builtin_assume_aligned(out, 32);
    a   = __builtin_assume_aligned(a, 32);
    b   = __builtin_assume_aligned(b, 32);
    for (size_t i = 0; i < (n & ~(size_t)7); ++i) {
        out[i] = a[i] * scale + b[i]; // Compiles to single-cycle AVX2 vfmadd213ps!
    }
}

// What the compiler generates around '*p = 42;' when compiled with -fsanitize=address:
// shadow_byte = *(int8_t *)(((uintptr_t)p >> 3) + 0x7fff8000);
// if (unlikely(shadow_byte != 0)) {
//     if ((int8_t)(((uintptr_t)p & 7) + 3) >= shadow_byte)
//         __asan_report_store4(p); // Instant stack trace with allocation/free history!
// }
// *p = 42;

uint64_t read_tsc_ordered(void) {
    uint32_t lo, hi;
    // volatile prevents deletion; rdtscp clobbers RAX, RDX, RCX and serializes instruction stream
    __asm__ __volatile__(
        "rdtscp"
        : "=a"(lo), "=d"(hi)
        :
        : "rcx", "memory"
    );
    return ((uint64_t)hi << 32) | lo;
}

