#include <errno.h>

// Mandatory read loop for an EPOLLET + O_NONBLOCK socket descriptor:
void drain_et_socket(int fd) {
    char buf[4096];
    for (;;) {
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n > 0) {
            process_bytes(buf, (size_t)n);
        } else if (n == 0) {
            close(fd); break; // EOF (peer closed connection)
        } else {
            if (errno == EINTR) continue;
            if (errno == EAGAIN || errno == EWOULDBLOCK) break; // Buffer fully drained!
            close(fd); break; // Fatal socket error
        }
    }
}

